  "comparison": {
    "features": ["Both plugins support multi-view functionalities similar to those found in Notion's database system.", "TableBase focuses on transforming existing Markdown tables while providing enhanced interactivity features.", "Rowbase creates entirely new structured databases stored locally as simple CSV files enriched with metadata."],
    "local_storage": ["Both TableBase and Rowbase operate primarily in a local-first manner, offering seamless interaction with Obsidian’s note-taking environment."],
    "vendor_lock_in": ["Neither plugin requires user accounts or sends telemetry data, ensuring full control over personal information."]
  }
}

